            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Totalitarianism in power invariably replaces all first-rate talents, regardless of their sympathies, with those crackpots and fools whose lack of intelligence and creativity is still the best guarantee of their loyalty.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Real power begins where secrecy begins.", Author = "Hannah Arendt" },
