            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The ideal subject of totalitarian rule is not the convinced Nazi or the convinced Communist, but people for whom the distinction between fact and fiction (i.e., the reality of experience) and the distinction between true and false (i.e., the standards of thought) no longer exist.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Man cannot be free if he does not know that he is subject to necessity, because his freedom is always won in his never wholly successful attempts to liberate himself from necessity.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "It is, in fact, far easier to act under conditions of tyranny than it is to think.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The essence of totalitarian government, and perhaps the nature of every bureaucracy, is to make functionaries and mere cogs in the administrative machinery out of men, and thus to dehumanise them.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The longer one listened to him, the more obvious it became that his inability to speak was closely connected with an inability to think, namely to think from the standpoint of somebody else.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "What stuck in the minds of these men who had become murderers was simply the notion of being involved in something historic, grandiose, unique (\"a great task that occurs once in two thousand years\"), which must therefore be difficult to bear.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Humanly speaking, no more is required, and no more can reasonably be asked, for this planet to remain a place fit for human habitation.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The trouble with Eichmann was precisely that so many were like him, and that the many were neither perverted nor sadistic, that they were, and still are, terribly and terrifyingly normal.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "No punishment has ever possessed enough power of deterrence to prevent the commission of crimes.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The greatest evil perpetrated is the evil committed by nobodies, that is, by human beings who refuse to be persons.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Power and violence are opposites; where the one rules absolutely, the other is absent. Violence appears where power is in jeopardy, but left to its own course it ends in power's disappearance.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The defiance of established authority, religious and secular, social and political, as a world-wide phenomenon may well one day be accounted the outstanding event of the last decade.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Revolutionaries do not make revolutions! The revolutionaries are those who know when power is lying in the street and when they can pick it up. Armed uprising by itself has never yet led to revolution.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "For the trouble with lying and deceiving is that their efficiency depends entirely upon a clear notion of the truth that the liar and deceiver wishes to hide. In this sense, truth, even if it does not prevail in public, possesses an ineradicable primacy over all falsehoods.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Could the activity of thinking as such, the habit of examining whatever happens to come to pass or to attract attention, regardless of results and specific content, could this activity be among the conditions that make men abstain from evil-doing?", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "Metaphysical fallacies contain the only clues we have to what thinking means to those who engage in it.", Author = "Hannah Arendt" },
