            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The emotions I feel are no more meant to be shown in their unadulterated state than the inner organs by which we live.", Author = "Hannah Arendt" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Hannah_Arendt", Text = "The moment we no longer have a free press, anything can happen.", Author = "Hannah Arendt" },
